import ast,base64,json,zlib,zipfile,xml.etree.ElementTree as ET
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DIR=ROOT/'zips/plugin.video.xship'
CHANGES=json.loads(zlib.decompress(base64.b64decode('')))
with zipfile.ZipFile(DIR/'plugin.video.xship-2026.10.20.162.zip') as zi:
    entries={i.filename:zi.read(i) for i in zi.infolist() if not i.is_dir()}
for path,text in CHANGES.items():
    if path.endswith('.py'):ast.parse(text)
    if path.endswith('.xml'):ET.fromstring(text)
    entries[path]=text.encode()
assert ET.fromstring(entries['plugin.video.xship/addon.xml']).get('version')=='2026.10.20.164'
assert b"_XSHIP_CHANGELOG_BUILD = '2026.10.20.164'" in entries['plugin.video.xship/service.py']
with zipfile.ZipFile(DIR/'plugin.video.xship-2026.10.20.164.zip','w',zipfile.ZIP_DEFLATED) as zo:
    for name,data in entries.items():zo.writestr(name,data)
(DIR/'changelog.txt').write_bytes(entries['plugin.video.xship/changelog.txt'])
print('Built xShip 2026.10.20.164: tested MVW fallback')
